/// Memoised accessors — call each at most once per key, cache the result.
class ShroudedPayload {
  const ShroudedPayload._();
  static final Map<String, String> _cache = <String, String>{};

  static String _pull(String key, List<int> payload) =>
      _cache.putIfAbsent(key, () => revealBytes(payload, _saltBytes, _streamLen));

  // ── endpoints
  static String pullEndpointUrl() => _pull('endpoint', _endpointUrl);
  static String pullGcdBaseUrl() => _pull('gcd', _gcdBaseUrl);
  static String pullAttributionKey() => _pull('attr', _attributionKey);
  static String pullMessagingProject() => _pull('msg', _messagingProject);

  // ── UA fragments (assembled by GadgetFingerprint)
  static String pullUaProduct() => _pull('ua_prod', _uaProduct);
  static String pullUaLinuxOpen() => _pull('ua_lo', _uaLinuxOpen);
  static String pullUaBuildLabel() => _pull('ua_bl', _uaBuildLabel);
  static String pullUaBuildClose() => _pull('ua_bc', _uaBuildClose);
  static String pullUaEngineLabel() => _pull('ua_el', _uaEngineLabel);
  static String pullUaEngineTail() => _pull('ua_et', _uaEngineTail);
  static String pullUaChromeLabel() => _pull('ua_cl', _uaChromeLabel);
  static String pullUaMobileSafari() => _pull('ua_ms', _uaMobileSafari);
  static String pullChromeVersion() => _pull('chrome_v', _chromeVersion);
  static String pullWebkitVersion() => _pull('webkit_v', _webkitVersion);

  // ── UA suffix tokens (user-mandated appid/appname pair)
  static String pullUaAppIdToken() => _pull('ua_aid', _uaAppIdToken);
  static String pullUaAppNameToken() => _pull('ua_anm', _uaAppNameToken);
  static String pullAppNameToken() => _pull('ua_name', _appNameToken);

  // ── JS enhancers injected into the WebView
  static String pullJsSafeAreaScript() => _pull('js_sa', _jsSafeAreaScript);
  static String pullJsKeyboardScript() => _pull('js_kb', _jsKeyboardScript);
  static String pullJsAutoplayScript() => _pull('js_ap', _jsAutoplayScript);
}
